/* ---------- copy and adapt at company scale: the ports that replace Store (backlog AS, part 1) ---------- */

/** The actions the command port runs: every shared action R1's access table names, less the `can…` checks they call. */
export function commandNames(): string[] {
  const helper = (fn: string) => /^(can|may)[A-Z]/.test(fn) || fn === 'reviewHeld' || fn === 'leaving';
  // A rule whose action has another name: `planGoal` works out a goal's save, and the `saveGoal` action runs it;
  // `saveMetricAsked` asks rule 1's Checks before `saveMetric` saves, and the `saveMetric` action runs it.
  const action: Record<string, string> = { planGoal: 'saveGoal', saveMetricAsked: 'saveMetric' };
  return [...new Set(ACCESS.flatMap((a) => a.code).map((r) => r.split('#')[1]!).filter((fn) => !helper(fn)).map((fn) => action[fn] ?? fn))];
}

/** How each test of storeContract (src/ports/contracts/store.ts) carries across: [its title, on the query and command ports]. */
export const CONTRACT_MAP: [string, string][] = [
  ['keeps a new workspace whole, and lists it', 'The `createWorkspace` command, then the query port: `workspaces()` lists it to its members and to nobody else (R1, rule 3); paging through `goals()` 50 at a time gives every goal once and none twice; `people()` and `teams()` likewise.'],
  ['saves a change-log entry and gives it back', 'The `addNote` command, sent with no actor, time or id; `activity()` gives the entry back with the signed-in person as its actor and the server’s time. A caller that sends its own actor, time or change-log entry is refused.'],
  ['saves a goal one version on, and refuses a save based on the version before it as stale', 'The same, through any command that changes a goal, with the versions the person saw (`Expectations`). Extended to every record two people can edit at once: people, teams, asks, decisions and views, which `Store` saves last-write-wins today.'],
  ['never lets a save to one workspace change another’s records', 'Every command, for a workspace the caller is a member of: a command that names a record stored under another workspace is refused and changes nothing (R1, rule 3). The database checks it as well as the server: what each row says, where a row already stored is kept, and a milestone’s stages through their goal (Faro’s migration 0038).'],
  ['keeps a module’s records whole, saves them with a commit, and removes and restores them with what they point to', 'Each module’s records are its own ports’ business: a module that owns records adds its own queries and commands (the metric library’s `metrics()` and `saveMetric`), and its rows are saved in the same transaction as the core command that names them. The core’s ports stay closed; nothing a module keeps widens them.'],
  ['issues an AI assistant token once, never keeps its secret, and revokes it', 'The `createToken` command returns the secret once and is refused for someone who isn’t an admin; no query ever returns the secret or its hash; `revokeToken` stops the token at once (R1, rule 5).'],
  ['deletes a workspace and everything in it', 'The `deleteWorkspace` command, admins only (`canDeleteWorkspace`); afterwards no query returns anything of it.'],
  ['resets the example only when it has one', 'Not carried across: the example, `hasExample` and `resetExample` are the demo’s plumbing. They stay with the demo’s own store.'],
];

/** AS part 3 (deep review A7): what a team copying Faro should leave behind, each with what to do instead. */
const dontCopy = () => GENERATED + [
  '# Don’t copy this',
  '',
  'Things in Faro that are right for a demo, or a shortcut taken on purpose, and wrong to carry into the internal app. Each says what Faro does, why, and what to do instead. The rest of the kit says what *to* copy.',
  '',
  '| In Faro | Why it is so | Instead |',
  '|---|---|---|',
  '| `api/mcp.js`, the AI tools’ server, is a 1.5 MB built bundle committed to the repository; CI fails a pull request that changes `server/` without rebuilding it (`npm run build:mcp`) | The host finds a function by its file before any build runs, so the built file has to be there | Build the server in your pipeline and deploy what it builds. Never commit a build: it conflicts on every merge and hides what changed |',
  '| One browser bundle, its first download held to a budget by `scripts/check-bundle.mjs` (over 300 KB compressed), with screens a first visit doesn’t need loaded when opened | The demo grew one screen at a time; the budget stops it growing and each release pays for what it adds | [R4](../requirements/internal/r4-scale-and-safety.md)’s budget is 300 KB for the first screen. Split by route from the start, and load each feature module only when it is switched on and opened |',
  '| The goals store loads a whole workspace into the browser, and the rules read it (`Store.load`, `Snapshot`) | 126 goals load in a moment, and every rule stays a pure function over plain rows | Read through [the query and command ports](ports-at-scale.md): paged summary rows in, one action and its input out, the server setting the actor, time and ids |',
  '| The actions run in the browser; the database only checks each row’s workspace and the version of a goal or review (`okr_commit`) | Faro has no server of its own beyond the AI tools’ endpoint | Run `src/domain/actions` on the server ([R1](../requirements/internal/r1-sign-in-and-access.md)): the browser asks, the server decides |',
  '| Demo plumbing beside the store port: the example workspace, resetting it and its storage key (`ExampleStore`: `hasExample`, `resetExample` in `src/data/store.ts`, the browser store’s alone since AX5; the `Store` port has neither) | The demo is the product people try first | Keep demo data out of the port: a seeding script for a test environment, never a method every adapter must carry |',
  '| Goal keys are worked out twice: in TypeScript before the save (`src/domain/goalKey.ts`) and by a database trigger at the save (migration 0021) | Two people adding goals at once must not get one key; the app shows a key before the database has given one | Give keys in one place, the server, and show “saving…” until it answers |',
  '| Sign-in by a link to one of the demo’s people, and access rules written for a demo ([access today](access-today.md)) | Anyone can try every role in a minute | Your platform’s single sign-on and roles ([R1](../requirements/internal/r1-sign-in-and-access.md)); nothing of the demo’s access survives |',
  '| The rules’ words are hand-written beside their worked examples (`src/spec/rules.ts`) | The examples run against the code, so a wrong number fails the spec | Copy the rules and their examples; treat the prose as a draft to check. The examples can’t drift; the sentences can |',
  '| Requirements for the demo and its builders sit among the core ones in `evals/requirements.json`: the demo under /demo, its storage, walkthroughs, the research hub, the name and icon, the home-screen launch, the reload after a deploy | They are Faro’s own requirements, and the evals check them like any other | Each requirement is tagged ([the requirements](../core/requirements.md)): build the ones tagged copy, do the ones tagged replace your platform’s way (the tag names the R), and leave out the ones tagged demo only |',
  '| `spec/core/schema.sql` is a Postgres and Supabase dump: row rules, `security definer` functions, a `storage.objects` policy, global text ids, no foreign key from a table to its workspace, indexes on one column, some rules held only by a check constraint | It is how Faro is stored, and the kit shows it so nothing is hidden | Design your own schema from [the data model](../core/data-model.md)’s “Keys, uniqueness and scope”; every limit the dump holds is on its rule’s page, under “Limits the records hold” |',
  '| A comment is stored as a change-log entry (`entity: \'note\'`, `addNote` in `src/domain/actions.ts`), and accepting a risk in a review is a note that starts with a fixed phrase (`acceptedReason` in `src/domain/decide.ts`) | The change log was already listed on the goal, so a comment came free; one more kind of decision would have needed a migration | Give comments a record of their own, and accepting a risk a decision kind of its own. The change log records that each happened; it isn’t where they live |',
  '| Telemetry (traces, logs and metrics) is written to the app’s own database and rolled up by a nightly job (`okr_telemetry_nightly`) | Faro has no observability platform, and the demo’s numbers are small | Send them to your platform’s observability ([R9](../requirements/internal/r9-observability.md)); keep nothing of it in the app’s database |',
  '| Formatting quirks are scored as rules: “-0” for a small negative number at 0 decimals, “1 pts” for a unit the singular rule doesn’t know ([the scorecard](../core/rules/scorecard.md)) | The scorecard file records what the code says, quirks included, so a change to the words is seen | They are in `scorecard-words.csv`, scored only when asked. Chase 100% on `scorecard.csv` and say numbers your own way: “0”, not “-0”, and the singular your platform’s words give |',
  '',
  'The scorecard’s words are scored in a file of their own (`scorecard-words.csv`, when asked): a rebuild in other words, or another language, still scores the rules in `scorecard.csv`.',
  '',
].join('\n');

const portsAtScale = () => GENERATED + [
  '# The ports at company scale',
  '',
  'For a team that copies Faro’s code and runs it for the whole company. [Swap the outside parts](adapters.md) gets Faro running on your platform at Faro’s size. This page is about the one part whose shape has to change on the way to 15,000 people: the goals store. Read [R1, sign-in and access](../requirements/internal/r1-sign-in-and-access.md) and [R4, scale and safety](../requirements/internal/r4-scale-and-safety.md) first; this page is the route to them.',
  '',
  '**Today:** the query port’s first cut is in Faro’s code (`Goals`, `src/ports/goals.ts`: `goals()`, `counts()` and `goal()`), answered in the browser and run against a contract whose cases are data (below). The rest of the query port and the command port’s server side are still a sketch. What Faro does have, and what makes the move mechanical, is that every rule and every action is a pure function: given what it reads, it returns what to save.',
  '',
  '## `Store` is the demo-scale port',
  '',
  '`Store` (`src/ports/store.ts`) has two working methods, and two narrower reads beside them that the app doesn’t use yet:',
  '',
  '- **`load(workspaceId)`** gives a whole `Snapshot`: every person, team, goal, check-in, ask, review and the whole change log. The rules take that `Snapshot` as their input; the app loads it again when the window regains focus and every two minutes, and the AI tools’ server loads it on every request.',
  '- **`commit(workspaceId, commit)`** saves the rows and change-log entries its caller already wrote. The caller runs the action, stamps the time from its own clock, writes the change-log entry with its own idea of who acted, and makes the ids. The database checks that every row belongs to the workspace (what each row says, where a row already stored is kept, and a milestone’s stages through their goal) and that a goal’s or review’s version hasn’t moved, and nothing else. It doesn’t check what a row points at: a goal saved to one workspace may name another workspace’s person as owner, team, cycle or parent goal, and a check-in another workspace’s goal. Refusing those is the server’s, by the same membership that decides who may save (R1). People, teams, asks, decisions and views are saved last-write-wins.',
  '- **`load(workspaceId, { from })`** (AX5 part 2) gives the same `Snapshot` with two kinds of record trimmed. Check-ins are kept only for goals in cycles that end on or after `from`, and always for the newest two cycles not removed (the year in use and the one in its wrap-up), however long ago they ended, so a year nobody follows with a next one never falls out of the window. Change-log entries are kept from `from` on, plus the anchors, kept at any age because rules read them whatever their age: comments (entity `note`), asks (`request`), a cycle’s own entries (`cycle`), people’s entries (`person`: an arrival is logged once), metrics’ entries (`metric`: their last change and former names), and import summaries (action `imported` or `undone`, or carrying what the import replaced). The snapshot’s `history` says what was left out: `from`, and `checkInCycles`, every cycle with any check-in in the whole workspace, so a rule asking whether a cycle has one needs no rows. With no window the load is whole and has no `history`.',
  '- **`history(workspaceId, { before, goalId, size })`** gives older change-log entries a page at a time, newest first: those strictly older than `before` (a time and an id) in the order time, then id, both descending, at most `size` (50 unless asked, never more than 100), narrowed to one goal when asked; `next` says where the following page starts, or is null at the end. Paging on with it never skips or repeats an entry. On a database it is a keyset read, `(at, id) < (before.at, before.id)`, which an index on `(workspace_id, at)` serves.',
  '',
  'That is right for the demo, which holds 126 made-up goals and trusts “Who are you?”. It is wrong for the internal app, for two reasons the requirements already state: **R4** (“Nothing loads a whole workspace”: 30,000 goals and 1.5 million check-ins a year), and **R1** (“The server enforces it … No key a browser holds can write”: an audit trail the caller writes isn’t one). So `Store` and its contract are for getting Faro running on your database. They are not the interface the internal app is built on.',
  '',
  'The rules for what a window keeps and how history pages are written once, in `src/ports/window.ts`; the browser store runs them as they are, the database stores put the same rules in their queries, and four cases in the store contract check all of them agree. The app loads with a window of about a year (`appWindow`, `LOAD_DAYS` in that file) and pages older entries into Activity and a goal’s History with `history`; rules that would need what a window leaves out say so instead of guessing (a year whose check-ins were left out stays, someone with no loaded mark is marked as left rather than deleted, an import older than the window can’t be undone). The AI tools’ `get_activity` pages with `history`; their server still loads the whole workspace, because the removal and undo tools read the log at any age.',
  '',
  '## What stays the same',
  '',
  '- **The rules**, in `src/domain`: weeks and plans, status, the projection, what a check-in must say, flags and needs attention, the scorecard, the change engine. Pure functions with no database, screen or network code (the layers lint keeps them so). Stage 1’s drill proves them, whichever port feeds them: it must still score 100%.',
  '- **The actions**, in `src/domain/actions.ts` and `src/domain/removal.ts`, and the change engine (`planChanges` in `src/domain/changeset.ts`). Each takes an `ActionContext` (what it reads, who acts, now, a way to make ids), checks who may do it, and returns a `Commit` or refuses with words a person can act on (`NotAllowed`). They move to the server unchanged.',
  '- **A save is one `Commit`**, kept all at once or not at all, with the versions it was based on.',
  '- **The other parts** keep their interfaces and contracts: `Clock`, `Files`, `NumberSource`, markups and feedback. `Identity` stops being a choice the browser makes: the server knows who is signed in ([R2](../requirements/internal/r2-single-sign-on.md)).',
  '',
  '## The query port: what screens and the AI tools read',
  '',
  'Reads are answered by the server, from summary rows ([R4](../requirements/internal/r4-scale-and-safety.md), rule 2), a page at a time. The port takes no actor: the server answers for the signed-in person, and only within workspaces they belong to.',
  '',
  '```ts',
  'interface GoalsQuery {',
  '  workspaces(): Promise<Workspace[]>;                                   // only the signed-in person’s',
  '  goals(ws: string, q: GoalQuery, page: PageAt): Promise<Page<GoalSummary>>;',
  '  counts(ws: string, q: GoalQuery): Promise<Record<StatusCode, number>>; // the same filter, counted from summaries',
  '  goal(ws: string, goalId: string): Promise<GoalPage>;                  // one goal with its check-ins, asks, decisions and history',
  '  search(ws: string, text: string, kinds: (\'goal\' | \'person\' | \'team\')[], page: PageAt): Promise<Page<Hit>>;',
  '  people(ws: string, q: PeopleQuery, page: PageAt): Promise<Page<Person>>;',
  '  teams(ws: string, page: PageAt): Promise<Page<TeamSummary>>;',
  '  activity(ws: string, q: ActivityQuery, page: PageAt): Promise<Page<Change>>;',
  '  asksFor(ws: string, personId: string, page: PageAt): Promise<Page<Ask>>;',
  '  review(ws: string, reviewId: string, page: PageAt): Promise<ReviewAgenda>;',
  '}',
  'type PageAt = { after: string | null; size: 50 };            // keyset: the next page starts after the last row’s key',
  'type Page<T> = { rows: T[]; next: string | null; total: number };',
  '```',
  '',
  '- **`GoalSummary`** is one live goal’s summary row: the goal’s own fields, and what the stage 1 rules say about it now: its status and what the numbers say, its flags, whether it needs attention and how it is being handled, the projection and the scorecard, its latest week and days without an update. The columns are those of [the conformance files](../conformance/README.md), so the conformance data proves the summaries.',
  '- **`GoalQuery`** is the Goals screen’s own filter and sort (`src/domain/query.ts`): search text, status, level, team, owner, kind, needs attention, and the rest. Today the browser applies it to the whole `Snapshot`; on the query port the server applies it to summary rows.',
  '- **Faro’s first cut** (AX5): `Goals` in `src/ports/goals.ts` has the three goal calls without the workspace argument (an adapter is made for one workspace): `goals({ query, scope, after, size })` → `{ rows, next, total, near? }`, `counts({ query, scope })` → `{ total, status, attention }` and `goal(id)`. `scope` names a Goals scope (`mine`, `team` for your team and the teams you lead, `watching`, `all`, or `team:<id>`), answered for the person asking: never a list of ids. With no sort, a list comes worst first (off, then at risk and stale, then on track, then the rest), then by title, never in stored order. A list row is `GoalSummary` without `checkIns` and `series`. Faro’s adapter (`src/adapters/localGoals.ts`) answers from the loaded workspace with the stage 1 rules; Home’s list of your goals and its counts, and Goals’ filtered list, near miss and switch count, read through it (`src/app/goals.ts`). Its contract, `goalsContract` (`src/ports/contracts/goals.ts`), runs [goals.csv](../conformance/goals.csv)’s cases, the four checks below, a scope by name and the order with no sort on any adapter; its cases are data in [contracts/goals.json](../conformance/contracts/goals.json), so the drill runs them on any build through a shim.',
  '- **Search** is the server search behind find-and-pick, the list bars and Find. Faro already calls it through a port of this shape: `Search` (`src/ports/search.ts`), `search(kind, { q, filters, sort, after, size })` → `{ total, rows, next, near? }`, with its contract (`searchContract`). `search()` and the list calls above (`people()`, `teams()`, and `goals()` for a picker) are that one call with a kind, and **kinds are open**: the core’s are goal, person, team and workspace, and a module registers its own (the metric library’s metric). It accepts a goal’s key (“G-48”) wherever it accepts a title; what a search matches is [finding things](../core/rules/finding.md). The near miss is optional: a server may never offer one. `byIds(kind, ids)` gives the rows for what a picker already holds, in the same words, someone marked as left included; and `suggest(kind, viewer, recents)` the six offered before typing (finding things, rule 6). A person search takes People’s filters, `team` (a team’s id, its lead counted wherever their own team is, or `-` for people in no team) and `admins` (`1`), and People, Teams and every picker list in its one order.',
  '- **New rules already take the query port’s shapes.** Since AR4 no rule added to `src/domain` takes the whole workspace (`Snapshot`): each takes the rows it reads, made by `src/app/reads.ts` from the loaded workspace today and from this port in the rebuild. The older rules that still take it are listed in `scripts/whole-workspace.json`, and the layers lint lets that list only shrink: they are the work left.',
  '- **Only `goal()` reads a goal’s check-ins.** Lists, counts, Home and the AI tools read summaries.',
  '',
  '## The command port: what people and the AI tools change',
  '',
  'A write names an action and gives its input. The caller never sends rows, a change-log entry, an actor, a time or an id.',
  '',
  '```ts',
  'interface GoalsCommands {',
  '  run<A extends ActionName>(ws: string, action: A, input: ActionInput[A], seen?: Expectations): Promise<ActionResult[A]>;',
  '}',
  '```',
  '',
  'On the server, for each command:',
  '',
  '1. **Who:** the signed-in person, or the person an MCP token belongs to (marked via MCP). Never a value from the caller.',
  '2. **What it reads:** only the records the action needs (the goal, its check-ins, its asks, the people named), not the workspace.',
  '3. **The context:** `now` from the server’s `Clock`, as a real instant ([R3](../requirements/internal/r3-time-zones.md)); ids made by the server.',
  '4. **The rule:** the same function from `src/domain`, unchanged. A refusal goes back with its words, the same words the app shows.',
  '5. **The save:** the `Commit` it returns, rows and change-log entries together in one transaction, refused as stale when a record has moved on from the version the person saw. A stale refusal isn’t the end: load what the command reads again, run the same rule with the same input on it, and save that, at most twice more (Faro’s dispatcher and AI tools do, AX6). Only a rule that now says no is shown, in its own words. A command whose input is a whole record as the person last saw it (a goal’s form, a review’s settings, a table of values) isn’t run again, since that would put back what the other person changed; nor is one the person confirmed against a preview, a read-back or a sheet saying what happens (making a goal active, removing it, marking someone as left, removing a team, undoing an import), since the re-run could do what they never saw. Either way the person is shown the latest and asked to check it and try again; a goal’s form keeps only the fields they changed. A re-run acts as the person among the latest people, and is refused if they have left since. Faro’s AI tools re-run every tool, since a tool names only what it changes, and say so in the reply.',
  '6. **The summaries** of every goal the save touched are worked out again in the same transaction (R4, rule 2).',
  '7. **The answer:** what the action gives back (a new id, a token’s secret once, a change set’s preview) and the refreshed summaries, so the screen updates without loading anything else.',
  '',
  'The browser may still run an action first to explain early (“Only admins can …” before a button is pressed), as Faro does; the server’s answer is the one that counts.',
  '',
  '**Faro already calls it this way** (backlog RD, AR3): every change goes through one dispatcher, `app.run(action, input)` (`src/app/state.tsx`), over one table of actions (`src/app/actions.ts`). The input names records by id; the dispatcher sets who acts, when and new ids, runs the rule from `src/domain`, saves its `Commit`, and shows Undo after a removal. The screens’ per-action methods are aliases of it. To put the command port on a server, replace the dispatcher’s body with a call to the server and keep the table’s names and inputs: no screen changes. `src/app/actions.test.ts` holds the table and the list below together, both ways.',
  '',
  `**The actions**, read from R1’s access table so the list can’t drift: ${commandNames().map((n) => `\`${n}\``).join(', ')}. \`planChanges\` is the change engine: check-ins, goal and plan edits, bulk edits and spreadsheets, with a preview (nothing saved) and an apply. Add \`createWorkspace\` and \`deleteWorkspace\`, which \`Store\` has as methods of its own. Each action’s input, result, who may and the words it refuses with are on [the actions](../core/actions.md), and the AI tools that do the same on [the AI tools](../core/tools.md).`,
  '',
  '## How each contract test carries across',
  '',
  `\`storeContract\`’s tests (\`src/ports/contracts/store.ts\`; its cases as data in [contracts/store.json](../conformance/contracts/store.json)) on records carry across like this:`,
  '',
  table(['`storeContract` test', 'On the query and command ports'], CONTRACT_MAP.map(([a, b]) => [cell(a), cell(b)])),
  '',
  'And five that `Store` has no equivalent of:',
  '',
  '1. **The summaries are the rules.** For the demo workspace, `goals()` in every week gives the status, flags, projection and scorecard in [the conformance files](../conformance/README.md) (R4, check 1).',
  '2. **The server refuses what the rules refuse.** For every line of [R1’s access table](../requirements/internal/r1-sign-in-and-access.md#who-may-change-what), someone outside its “who” is refused by the command port, called directly with their own sign-in, with the words the app shows (R1, check 1).',
  '3. **Keyset paging** never skips or repeats a row while rows are added or changed between pages (R4).',
  '4. **No read is larger than a page**, and only `goal()` reads a goal’s check-ins (R4, check 3).',
  '5. **The server refuses a switched-off module’s writes.** With a module switched off in a workspace, every command that would write its records (for Reviews: a review, a note said in one, a question or action newly raised in one, a goal newly proposed in one) is refused with the switched-off sentence and changes nothing, whatever the caller last loaded. Faro checks it in the browser and in the AI tools’ save, from the switches loaded with the workspace, so a tab open since before the switch is refused only from its next reload; the internal app reads the switch on the server, at the save.',
  '',
  '## A route from Faro’s code',
  '',
  'In steps, each of which leaves a working app and stage 1’s drill at 100%:',
  '',
  '1. **Commands first.** Put the command port on a server and move the app’s and the AI tools’ saves onto it, with `Store` still underneath: the server loads, runs the action, commits. Trust is fixed (the server decides who acted, when, and whether it is allowed), scale not yet.',
  '2. **Summaries.** Keep a summary row per live goal, written in the same save; move Home and Goals onto `goals()` and `counts()`, then the other screens one at a time.',
  '3. **Narrow reads.** Replace the server’s whole-workspace load with what each action reads, then retire `Store.load` and the two-minute reload.',
  '',
  '## Gaps in the kit',
  '',
  '- Of the query port, Faro has `goals()`, `counts()` and `goal()` (`src/ports/goals.ts`) with a contract; the other calls (`people()`, `teams()`, `activity()`, `asksFor()`, `review()`) are still sketches, and the command port has no contract test: [the actions](../core/actions.md) say what each command takes, gives back and refuses, but nothing runs them against a server yet. The command port’s calling side does exist (`app.run`, above), but its body still runs the rule in the browser and saves through `Store`.',
  '- Most rule functions take a whole `Snapshot`. [What each action and summary reads](reads.md) lists, worked out by running them, the records each action uses and the lists it reads whole today, which is where step 3 starts; and proves a goal’s summary row, being handled included, needs only that goal’s own records. [Accepting scale](scale.md) has a company-size workspace to test against.',
  '- Home’s goal list and counts and Goals’ filtered list and counts read through the query port; the other screens, and the rest of Home and Goals (trees, groups, reviews, asks), read the app’s loaded state directly, and which query each needs isn’t listed.',
  '- Goal keys are worked out in the rules and again by a database trigger (`supabase/migrations/0021_goal_keys.sql`); at company scale the server’s is the one that counts.',
  '',
].join('\n');

/** Every file under spec/rebuild/, by path from the repository root. `harness` is scripts/drill.mjs's text. */
/** One file's entry in scripts/browser-storage.json: what it keeps in the browser and where the internal app keeps it. */
export interface BrowserState { uses: number; keeps: string; server: string }

export function rebuildFiles(mods: ModuleWithRebuild[], rows: Stage1Files, harness: string, browser: Record<string, BrowserState> = {}, later: DrillFiles = {}): Record<string, string> {
  const all = stages(mods);
  const out: Record<string, string> = {
    'spec/rebuild/README.md': guide(all, rows),
    'spec/rebuild/stage-1-core-rules.md': stage1(rows),
    'spec/rebuild/stage-2-core-data.md': stage2(later),
    'spec/rebuild/stage-3-core-screens.md': stage3(later),
    'spec/rebuild/adapters.md': adapters(browser),
    'spec/rebuild/ports-at-scale.md': portsAtScale(),
    'spec/rebuild/dont-copy.md': dontCopy(),
    'spec/rebuild/drill.mjs': '// Generated by npm run spec from scripts/drill.mjs. Edit that file, not this copy.\n' + harness,
  };
  for (const s of all) if (s.module) out[`spec/rebuild/${s.file}`] = moduleStage(s, mods.find((m) => m.id === s.module)!, all);
  return out;
}
